    <link rel="stylesheet" href="https://fontsapi.zeoseven.com/2/main/result.css" crossorigin>
  </noscript>
  <script>
    (() => {
      const VALID_THEMES = new Set(['warm-white', 'paper-white', 'dark', 'green']);
      const savedTheme = localStorage.getItem('kivotos-theme') || localStorage.getItem('theme') || 'warm-white';
      const initialTheme = VALID_THEMES.has(savedTheme) ? savedTheme : 'warm-white';
      window.__initialTheme = initialTheme;
      document.documentElement.style.colorScheme = initialTheme === 'dark' ? 'dark' : 'light';
    })();
  </script>
    <link rel="preconnect" href="https://testingcf.jsdelivr.net" crossorigin>
  <!-- 这里原本是 22 个内联 <style>（共 171KB）。
       每条 AI 消息都是一个独立 iframe，内联就等于每层重新解析一遍，所以抽成外链。
       注意它是渲染阻塞的：取不到时浏览器会以无样式状态渲染正文。 -->
