      '红蔷薇': { color: '#c4332b', avatar: charAvatar('红蔷薇'), aliases: ['红蔷薇'], given_name: '红蔷薇' },
      '斯黛拉': { color: '#8b63b8', avatar: charAvatar('斯黛拉'), aliases: ['斯黛拉', '伊贺栖寅'], given_name: '斯黛拉' },
      '璃亚梦': { color: '#e84390', avatar: charAvatar('璃亚梦'), aliases: ['璃亚梦', '梦见璃亚梦'], given_name: '璃亚梦' }
    };

    // 内置角色名单（有头像的角色常驻，不依赖MVU）
    const BUILTIN_CHAR_NAMES = Object.keys(CHARACTER_CONFIG).filter(name => CHARACTER_CONFIG[name]?.avatar);

    // ==================== MVU 接入层 ====================
    const getCore = () => {
      try {
        const win = window.parent || window;
        const $ = window.jQuery || win.jQuery;
        return { window: win, $, getDB: () => win.AutoCardUpdaterAPI || window.AutoCardUpdaterAPI };
      } catch (e) {
        return { window: window, $: window.jQuery, getDB: () => window.AutoCardUpdaterAPI };
      }
    };

    const mvuState = {
      ready: false, mvu: null,
      check: () => {
        const win = getCore().window;
        if (typeof win.Mvu === 'undefined' || typeof win.Mvu.getMvuData !== 'function' || typeof win.Mvu.replaceMvuData !== 'function') {
          mvuState.ready = false; mvuState.mvu = null; return false;
        }
        mvuState.ready = true; mvuState.mvu = win.Mvu; return true;
      }
    };

    const fetchLatestMvuData = () => {
      let finalData = {};
      try {
        if (mvuState.ready || mvuState.check()) {
          const mvuData = mvuState.mvu.getMvuData({ type: 'message', message_id: 'latest' });
          if (mvuData?.stat_data && Object.keys(mvuData.stat_data).length > 0) {
            finalData = mvuData.stat_data;
          } else {
            const chatData = mvuState.mvu.getMvuData({ type: 'chat' });
            if (chatData?.stat_data && Object.keys(chatData.stat_data).length > 0) finalData = chatData.stat_data;
          }
        }
      } catch (e) { console.warn('[正文美化] MVU:', e); }
      return finalData;
    };

    const applyMvuPatches = (patches) => {
      try {
        if (!mvuState.ready && !mvuState.check()) return false;
        const scopes = [{ type: 'message', message_id: 'latest' }, { type: 'chat' }];
        for (const scope of scopes) {
          const mvuData = mvuState.mvu.getMvuData(scope);
          if (!mvuData?.stat_data || Object.keys(mvuData.stat_data).length === 0) continue;
          patches.forEach(patch => {
            const parts = patch.path.split('/').filter(Boolean);
            if (patch.op === 'replace' || patch.op === 'add') {
              let obj = mvuData.stat_data;
              for (let i = 0; i < parts.length - 1; i++) { if (!obj[parts[i]] || typeof obj[parts[i]] !== 'object') obj[parts[i]] = {}; obj = obj[parts[i]]; }
              obj[parts[parts.length - 1]] = patch.value;
            } else if (patch.op === 'remove') {
              let obj = mvuData.stat_data;
              for (let i = 0; i < parts.length - 1; i++) { if (!obj[parts[i]]) return; obj = obj[parts[i]]; }
              delete obj[parts[parts.length - 1]];
            }
          });
          mvuState.mvu.replaceMvuData(mvuData, scope);
          return true;
        }
        return false;
      } catch (e) { console.warn('[正文美化] MVU patch:', e); return false; }
    };
    // ==================== 直播间 <LiveRoom> ====================
    /* 直播间的表和算法都在 外部部署/V20260826/辅助计算脚本.js（parent.LinjiangAux）：
       礼物价格与人气点数、大航海档位、数量档位、牌子等级公式、名字折叠、以及一切写入。
       本文件同源，直接调，不用 postMessage。
       拿不到脚本时只有关注/取关直接写 MVU，其它消费动作仍保持只读，不在卡片里另算一套。 */
    function lrAux() {
      try {
        const win = window.parent || window;
        const api = win.LinjiangAux || window.LinjiangAux;
        return (api && api.roomAction) ? api : null;
      } catch (e) { return null; }
    }
    const LR_MENU_FALLBACK = { 礼物: [], 大航海: [], 数量档位: [1, 10, 66, 233], 醒目留言档位: [30, 50, 100], 资源域名: 'https://anchor.bolt.qzz.io' };

    /* 图片地址过一遍素材缓存（外部部署/V20260826/素材缓存脚本.js，挂在酒馆窗口上）。
       命中返回 blob: 地址，等于这一张图不出网；没装那个脚本、或者这个源不许跨源
       fetch（图床没给 ACAO）时原样返回远程地址，行为跟以前一样。
       卡片每条消息重渲染一次，所以这层省下来的是每次重渲染的那一轮请求。 */
    function assetUrl(remote) {
      const raw = String(remote || '');
      if (!raw) return raw;
      try {
        const win = window.parent || window;
        const api = win.LinjiangAssets || window.LinjiangAssets;
        return (api && typeof api.url === 'function') ? (api.url(raw) || raw) : raw;
      } catch (e) { return raw; }
    }
    function lrMenu() {
      const aux = lrAux();
      if (!aux) return LR_MENU_FALLBACK;
      try { return aux.roomMenu() || LR_MENU_FALLBACK; } catch (e) { return LR_MENU_FALLBACK; }
    }
    /* 这里原来有一张 LR_HOSTS：每个主播的封面文件名、档期、人气、牌子名。已经删掉——
       本文件只负责展示，不存表也不存数值。现在：
         档期 / 牌子名 / 底盘热度 / 大航海  → 读 MVU 的 系统配置.直播间.<名>
         热度                              → 读 MVU 的 对象信息.<名>.直播.热度
         封面                              → 有插画的角色随机取一张 SFW 通用图；
                                             自定义主播取开局页存进 localStorage 的那张
       主播名单也不再由这张表决定，改成看 对象信息 里有谁。 */
    const LR_TIER = { jian: '舰长', ti: '提督', du: '总督' };
    const LR_TIER_KEY = { '舰长': 'jian', '提督': 'ti', '总督': 'du' };
    const LR_TYPE_KEY = { '普通': 'chat', '舰长': 'chat', '提督': 'chat', '总督': 'chat', '礼物': 'gift', '醒目留言': 'sc', '进入': 'enter', '系统': 'sys' };
    /* 这里原来有六张表：礼物价格、人气点数、礼物图标、大航海档位、数量档位、醒目留言档位。
       全部搬到 辅助计算脚本.js，改从 lrMenu() 取。同一件礼物的价格/点数/图标原来分在
       三张表里，现在是一行。 */
    const LR_DEMO = `主播: 塔菲
主播说: 辛苦了。今晚先把加班那条醒目留言念了。
弹幕:
- 类型: 普通 名字: 云庭7楼 内容: 来了，电梯刚好卡在十三层
- 类型: 舰长 名字: 阿初 内容: 今日发型是认真的
- 类型: 提督 名字: 深海灯 内容: 王牌级杂谈，节奏稳
- 类型: 总督 名字: 临江夜航 内容: 别被火箭带跑
- 类型: 礼物 名字: 鼓岭晚风 礼物: 干杯 数量: 10
- 类型: 醒目留言 名字: 西洲加班人 金额: 30 内容: 加班到现在，求一句辛苦了
- 类型: 进入 名字: 湖滨卡座
- 类型: 系统 内容: 匿名棺 已被禁言`;

    /* 名字折叠（永雏塔菲→塔菲）也归辅助脚本，跟 mvuzod.js 的 GIRL_NAME_ALIAS 同一份。
