    function lrEl(root, key) { return root.querySelector('[data-lr="' + key + '"]'); }

    function lrPrefix(item) {
      return (item.medal ? `<span class="medal">${lrEsc(item.medal)}</span>` : '')
        + (item.tier ? `<span class="bdg ${item.tier}">${LR_TIER[item.tier] || ''}</span>` : '');
