      for (let i = 0; i < names.length; i++) {
        const name = names[i];
        if (name.length > 1 && raw.indexOf(name) !== -1 && name.length > best.length) {
          best = name;
          bestHit = EVT_NODE_ART.byName[name];
        }
      }
      if (bestHit) return bestHit;
      const district = parts[0] || raw;
      for (let i = 0; i < EVT_DISTRICT_PLATES.length; i++) {
        const key = EVT_DISTRICT_PLATES[i][0];
        if (district.indexOf(key) !== -1 || raw.indexOf(key) !== -1) {
          return { file: EVT_DISTRICT_PLATES[i][1] };
        }
      }
      return { file: 'overview_night.webp' };
    }
    function evtArtFocus(hit) {
      const nx = Number(hit && hit.nx);
      const ny = Number(hit && hit.ny);
      if (!Number.isFinite(nx) || !Number.isFinite(ny)) return '';
      const zoom = 2.27;
      const m = 0.5 / zoom;
      const cx = Math.min(1 - m, Math.max(m, nx));
      const cy = Math.min(1 - m, Math.max(m, ny));
      return '--nx:' + (cx * 100).toFixed(2) + '%;--ny:' + (cy * 100).toFixed(2) + '%;--zoom:' + zoom;
    }

    function evtSplitFields(line, keys) {
      const text = String(line || '');
      const re = new RegExp('(' + keys.join('|') + ')\\s*[:：]', 'g');
      const hits = [];
      let m;
      while ((m = re.exec(text))) hits.push({ key: m[1], at: m.index, end: m.index + m[0].length });
      if (!hits.length) return null;
      const fields = {};
      for (let i = 0; i < hits.length; i++) {
        const to = i + 1 < hits.length ? hits[i + 1].at : text.length;
        fields[hits[i].key] = text.slice(hits[i].end, to).trim();
      }
      return fields;
    }

    function evtMergeOpt(opt, fields) {
      if (!fields) return opt;
      if (fields.分类) opt.分类 = fields.分类;
      if (fields.选项) opt.选项 = fields.选项;
      if (fields.门槛) opt.门槛 = fields.门槛;
      if (fields.结算) opt.结算 = fields.结算;
      return opt;
    }

    function parseSuddenEvent(raw) {
      const decoded = decodeHtmlEntities(String(raw || ''));
      const evt = { 区域: '', 场所: '', 标题: '', 简述: '', 对象: '', 时段: '', 私密度: '', 选项: [] };
      let inOpts = false;
      let current = null;
      const flush = () => { if (current && (current.选项 || current.分类)) evt.选项.push(current); current = null; };
      decoded.split(/\r?\n/).forEach((line) => {
        const trimmed = line.trim();
        if (!trimmed) return;
        if (/^选项\s*[:：]\s*$/.test(trimmed)) { inOpts = true; return; }
        if (/^[-•]\s+/.test(trimmed)) {
          inOpts = true;
          flush();
          current = evtMergeOpt({ 分类: '', 选项: '', 门槛: '', 结算: '' }, evtSplitFields(trimmed.replace(/^[-•]\s+/, ''), ['分类', '门槛', '选项', '结算']));
          if (!current) current = { 分类: '', 选项: trimmed.replace(/^[-•]\s+/, ''), 门槛: '', 结算: '' };
          return;
        }
        if (inOpts && current && /^\s/.test(line)) {
          evtMergeOpt(current, evtSplitFields(trimmed, ['分类', '门槛', '选项', '结算']));
          return;
        }
        const fm = trimmed.match(/^(区域|场所|标题|简述|对象|时段|私密度)\s*[:：]\s*(.*)$/);
        if (fm) {
          inOpts = false;
          flush();
          evt[fm[1]] = fm[2].trim();
        }
      });
      flush();
      return evt;
    }

    function evtParseGains(text) {
      return String(text || '').split(/[,，]/).map((part) => {
        part = part.trim();
        if (!part) return null;
        let m = part.match(/^(.+?)\s*([+\-]\d+)\s*$/);
        if (m) return [m[1].trim(), m[2]];
        m = part.match(/^(.+?)\s*(?:→|->|=>|[:：])\s*(.+)$/);
        if (m) return [m[1].trim(), m[2].trim()];
        m = part.match(/^(.+?)(重置|归零)$/);
        if (m) return [m[1].trim(), m[2]];
        return [part, ''];
      }).filter((row) => row && row[0]);
    }

    function evtGainMeta(key) {
      if (EVT_GAIN_MAP[key]) return EVT_GAIN_MAP[key];
      if (/经验$/.test(key)) return ['star', 'gold'];
      return ['sparkle', ''];
    }

    function evtIsSolo(name) {
      const s = String(name || '').trim();
      return !s || s === '无' || s === '独行' || s === 'null' || s === 'none';
    }

    function evtCanonName(name) {
      const raw = String(name || '').trim();
      if (!raw) return '';
      if (typeof normalizeDisplayName === 'function') {
        const n = normalizeDisplayName(raw);
        return n === '角色' ? raw : n;
      }
      return raw;
    }

    function evtCharOf(name) {
      const canon = evtCanonName(name) || name;
      const cfg = (typeof CHARACTER_CONFIG !== 'undefined' && CHARACTER_CONFIG[canon]) || null;
      if (cfg) {
        const avatar = cfg.avatar || (typeof getAvatarFromCache === 'function' ? getAvatarFromCache(canon) : '');
        return { name: canon, color: cfg.color || '#9aa4dd', avatar: avatar || '' };
      }
      const cached = typeof getAvatarFromCache === 'function' ? getAvatarFromCache(canon) : '';
      let h = 0;
      for (const ch of String(canon)) h = (h * 31 + ch.codePointAt(0)) % 360;
      return { name: canon, color: 'hsl(' + h + ' 46% 62%)', avatar: cached || '' };
    }

    function evtReadStat() {
      try {
        const data = fetchLatestMvuData() || {};
        if (data.世界信息 || data.对象信息 || data.玩家信息) return data;
      } catch (e) { }
      if (location.protocol === 'file:') {
        return {
          世界信息: { 时间: { 时段: '暮' }, 位置: { 私密度: 4 } },
          对象信息: EVT_FILE_GIRL,
          玩家信息: { 同行: '塔菲' }
        };
      }
      return {};
    }

    function evtGirl(stat, name) {
      const girls = (stat && stat.对象信息) || {};
      const canon = evtCanonName(name);
      return girls[canon] || girls[name] || {};
    }

    function evtHasStats(girl) {
      return !!(girl && (girl.羁绊 || girl.生理));
    }

    function evtReqNumber(value) {
      if (value == null || value === '') return null;
      const n = Number(value);
      return Number.isFinite(n) ? n : null;
    }

    /* 门槛只判断稳定、结构明确的数值字段。
       心情、背包、异常状态等自由文本条件留给正文判断，不参与按钮灰置。 */
    function evtEvalReq(req, girl, player) {
      if (!req) return true;
      const bond = (girl && girl.羁绊) || {};
      const phy = (girl && girl.生理) || {};
      const ctx = {
        好感度: evtReqNumber(bond.好感度),
        顺从度: evtReqNumber(bond.顺从度),
        性欲度: evtReqNumber(phy.性欲度),
        体力: evtReqNumber(player && player.体力),
        对象体力: evtReqNumber(phy.体力),
        尿意: evtReqNumber(phy.尿意),
        金钱: evtReqNumber(player && player.金钱)
      };
      let ok = true;
      let hit = false;
      const re = /(好感度|顺从度|性欲度|对象体力|体力|尿意|金钱)\s*(>=|<=|==|[≥≤=＜＞><])\s*(-?\d+(?:\.\d+)?)/g;
      let m;
      while ((m = re.exec(String(req)))) {
        hit = true;
        const actual = ctx[m[1]];
        const op = String(m[2]).replace('≥', '>=').replace('≤', '<=').replace('＞', '>').replace('＜', '<');
        const expected = Number(m[3]);
        if (actual == null) ok = false;
        else if (op === '>=' && !(actual >= expected)) ok = false;
        else if (op === '<=' && !(actual <= expected)) ok = false;
        else if (op === '>' && !(actual > expected)) ok = false;
        else if (op === '<' && !(actual < expected)) ok = false;
        else if ((op === '=' || op === '==') && actual !== expected) ok = false;
      }
      // 没有可识别数值条件时不由冷代码设锁。
      return hit ? ok : true;
    }

    function evtGainsHtml(list) {
      return list.map(([k, v]) => {
        const meta = evtGainMeta(k);
        const num = /^[+\-]\d/.test(String(v));
        const down = /^-\d/.test(String(v));
        const tone = meta[1] ? ' data-tone="' + meta[1] + '"' : '';
        return '<span class="evt-gain' + (down ? ' down' : '') + '"' + tone + '>'
          + evtIc(meta[0])
          + '<span class="k">' + evtEsc(k) + '</span>'
          + '<span class="v' + (num ? '' : ' word') + '">' + evtEsc(v) + '</span>'
          + '</span>';
      }).join('');
    }

    function evtChoicePayload(option, objectName) {
      const gainText = (option.结算 || []).map(([k, v]) => {
        const value = String(v || '');
        return /^[+\-]\d/.test(value) || value === '重置' || value === '归零'
          ? `${k}${value}`
          : `${k}→${value}`;
      }).join('，');
      return encodeURIComponent(JSON.stringify({
        对象: objectName || '',
        门槛: option.门槛 || '',
        选项: option.选项 || '',
        结算: gainText
      }));
    }

    function evtChoiceData(button) {
      try { return JSON.parse(decodeURIComponent(button.dataset.evtChoice || '')) || {}; }
      catch (err) { console.warn('[正文美化] 突发事件选项解析失败', err); return null; }
    }

    function evtRefreshChoice(button, stat) {
      const payload = evtChoiceData(button);
      if (!payload) return false;
      const data = stat || evtReadStat();
      const player = (data && data.玩家信息) || {};
      let objectName = payload.对象 || '';
      if (evtIsSolo(objectName) && player.同行) objectName = player.同行;
      const girl = evtIsSolo(objectName) ? {} : evtGirl(data, objectName);
      const met = !payload.门槛 || evtEvalReq(payload.门槛, girl, player);
      button.classList.toggle('locked', !met);
      button.disabled = !met;
      button.setAttribute('aria-disabled', met ? 'false' : 'true');
      button.title = met ? '点击选择此行动' : `数值条件未满足：${payload.门槛}`;
      const req = button.querySelector('.evt-req');
      if (req && payload.门槛) {
        req.classList.toggle('met', met);
        req.innerHTML = evtIc(met ? 'check' : 'lock') + evtEsc(payload.门槛);
      }
      return met;
    }

    function evtRefreshChoices(root) {
      const stat = evtReadStat();
      (root || document).querySelectorAll('.evt-opt[data-evt-choice]').forEach((button) => evtRefreshChoice(button, stat));
    }

    function bindSuddenEventEvents() {
      if (window.__suddenEventChoicesBound) return;
      window.__suddenEventChoicesBound = true;
      document.addEventListener('click', (ev) => {
        const button = ev.target.closest && ev.target.closest('.evt-opt[data-evt-choice]');
        if (!button) return;
        // 点击时重新读取 MVU，防止旧卡片按挂载时的过期数值放行。
        if (!evtRefreshChoice(button)) { ev.preventDefault(); return; }
        const payload = evtChoiceData(button);
        if (!payload || !String(payload.选项 || '').trim()) return;
        ev.preventDefault();
        const gains = String(payload.结算 || '').trim();
        const message = `选择突发事件选项：${payload.选项}${gains ? `；结算：${gains}` : ''}`;
        if (!lrSendToChat(message)) console.warn('[正文美化] 突发事件选项发送失败');
      });

      // MVU 更新后，当前页面中已经显示的事件卡也重新计算数值门槛。
      try {
        const win = getCore().window;
        const eventOnFn = win.eventOn || window.eventOn;
        if (typeof eventOnFn === 'function' && (mvuState.ready || mvuState.check())) {
          const eventName = mvuState.mvu?.events?.VARIABLE_UPDATE_ENDED;
          if (eventName) eventOnFn(eventName, () => evtRefreshChoices(document));
        }
      } catch (e) { console.warn('[正文美化] 突发事件 MVU 状态监听失败', e); }
    }

    function evtPips(n) {
      const x = Math.max(0, Math.min(5, Number(n) || 0));
      let h = '';
      for (let i = 1; i <= 5; i++) h += '<s class="' + (i <= x ? 'on' : '') + '"></s>';
      return '<span class="evt-pips">' + h + '</span>';
    }

    function renderSuddenEvent(raw, idx) {
      const parsed = parseSuddenEvent(raw);
      const stat = evtReadStat();
      const world = (stat && stat.世界信息) || {};
      const player = (stat && stat.玩家信息) || {};
      const loc = world.位置 || {};
      const time = world.时间 || {};

      if (evtIsSolo(parsed.对象) && player.同行) parsed.对象 = player.同行;
      const area = parsed.区域 || loc.区域 || '';
      const place = parsed.场所 || loc.场所 || '';
      const phase = parsed.时段 || time.时段 || '';
      const privacy = parsed.私密度 !== '' ? parsed.私密度 : loc.私密度;
      const title = parsed.标题 || place || '突发事件';
      const girl = evtIsSolo(parsed.对象) ? {} : evtGirl(stat, parsed.对象);
      const bond = girl.羁绊 || {};
      const phy = girl.生理 || {};
      const opts = parsed.选项.map((o) => {
        const cat = EVT_CATS.indexOf(o.分类) !== -1 ? o.分类 : (o.分类 || '日常');
        const met = evtEvalReq(o.门槛, girl, player);
        return { 分类: cat, 选项: o.选项, 门槛: o.门槛, 结算: evtParseGains(o.结算), 达成: met };
      });
      const open = opts.filter((o) => !o.门槛 || o.达成);
      const mainCat = (open[open.length - 1] || opts[0] || { 分类: '日常' }).分类;
      const plateHit = evtPlateHit(area);
      const plate = plateHit.file;
      const areaLabel = String(area).replace(/[·.]/g, ' · ').replace(/\s+/g, ' ').trim();

      let castHtml = '';
      let bondsHtml = '';
      if (!evtIsSolo(parsed.对象)) {
        const cc = evtCharOf(parsed.对象);
        const mood = bond.心情 || '';
        const abn = Array.isArray(phy.异常状态) ? phy.异常状态 : [];
        const face = cc.avatar
          ? '<img src="' + evtAttr(cc.avatar) + '" alt="" loading="lazy" onerror="this.remove()"><i>' + evtEsc((cc.name || '?')[0]) + '</i>'
          : '<i>' + evtEsc((cc.name || '?')[0]) + '</i>';
        castHtml = '<div class="evt-cast" style="--ac:' + evtAttr(cc.color) + '">'
          + '<span class="evt-face">' + face + '</span>'
          + '<div class="evt-who"><span class="nm">' + evtEsc(cc.name) + '<em>同行</em></span>'
          + '<span class="st">'
          + (mood ? '<span class="evt-mood">' + evtIc('smile') + evtEsc(mood) + '</span>' : '')
          + abn.map((s) => '<span class="evt-abn">' + evtIc('sparkle') + evtEsc(s) + '</span>').join('')
          + '</span></div></div>';
        if (evtHasStats(girl)) {
          bondsHtml = '<span class="evt-bond" data-k="好感度">' + evtIc('heart') + '<span class="bk">好感</span><span class="bv">' + evtEsc(bond.好感度 ?? 0) + '</span></span>'
            + '<span class="evt-bond" data-k="顺从度">' + evtIc('sakura') + '<span class="bk">顺从</span><span class="bv">' + evtEsc(bond.顺从度 ?? 0) + '</span></span>';
        }
      }

      const optsHtml = '<ul class="evt-opts">' + opts.map((o) => {
        const locked = !!(o.门槛 && !o.达成);
        const req = o.门槛
          ? '<span class="evt-req' + (o.达成 ? ' met' : '') + '">' + evtIc(o.达成 ? 'check' : 'lock') + evtEsc(o.门槛) + '</span>'
          : '';
        return '<li><button class="evt-opt' + (locked ? ' locked' : '') + '" data-cat="' + evtAttr(o.分类) + '" data-evt-choice="' + evtAttr(evtChoicePayload(o, parsed.对象)) + '" type="button"' + (locked ? ' disabled aria-disabled="true"' : ' aria-disabled="false"') + '>'
          + '<span class="bar"></span><span class="evt-cat">' + evtEsc(o.分类) + '</span>'
          + '<span class="col"><span class="act">' + evtEsc(o.选项) + '</span>'
          + '<span class="sub">' + req + evtGainsHtml(o.结算) + '</span></span>'
          + '<span class="evt-go">' + EVT_IC.go + '</span></button></li>';
      }).join('') + '</ul>';

      const artFocus = evtArtFocus(plateHit);
      /* 主用 Pages 上那份底图（先过素材缓存，命中就是 blob: 不出网），
         失败再退到仓库里的相对路径 —— 那条只在从仓库直接打开这页时有效，
         酒馆的 about:srcdoc 没有 base URL，解析不出来。顺序反过来的话，
         酒馆里每次渲染都要先浪费一次注定失败的请求。 */
      const plateFar = EVT_PLATE_CDN + plate;
      const art = '<div class="evt-art"' + (artFocus ? ' style="' + artFocus + '"' : '') + '><img src="' + evtAttr(assetUrl(plateFar))
        + '" data-evt-far="' + evtAttr(plateFar) + '" data-evt-local="' + evtAttr(EVT_PLATE_LOCAL + plate)
        + '" alt="" loading="lazy" onerror="'
        + 'if(this.dataset.evtFar&&this.src!==this.dataset.evtFar){this.src=this.dataset.evtFar;delete this.dataset.evtFar}'
        + 'else if(this.dataset.evtLocal){this.src=this.dataset.evtLocal;delete this.dataset.evtLocal}'
        + 'else this.remove()"></div>';

      return '<div class="evt-wrap"><div class="evt evt-a" data-cat="' + evtAttr(mainCat) + '" data-evt-idx="' + (idx || 0) + '"><div class="evt-glass">'
        + '<div class="evt-edge"></div>'
        + '<div class="stage">'
        + art
        + (place ? '<span class="plate">' + evtIc('mapPin') + evtEsc(place) + '</span>' : '')
        + castHtml
        + '<div class="spacer"></div>'
        + '<div class="head">'
        + '<span class="evt-eyebrow">' + evtIc('sparkle') + '突发事件' + (areaLabel ? '<s>/</s>' + evtEsc(areaLabel) : '') + '</span>'
        + '<h3 class="evt-title">' + evtEsc(title) + '</h3>'
        + '<div class="evt-metas">'
        + (phase ? '<span class="evt-mp">' + evtIc('moon') + evtEsc(phase) + '</span>' : '')
        + (privacy !== '' && privacy != null ? '<span class="evt-mp">私密' + evtPips(privacy) + '</span>' : '')
        + bondsHtml
        + '</div>'
        + (parsed.简述 ? '<p class="evt-brief">' + evtEsc(parsed.简述) + '</p>' : '')
        + '</div></div>'
        + '<div class="body">' + optsHtml + '</div>'
        + '</div></div></div>';
    }

    function initEvtCards() {
      bindSuddenEventEvents();
      const content = document.getElementById('readingContent');
      const raw = content && (content.textContent || '');
      const slotOpen = ENABLE_DEMO_CONTENT && (location.protocol === 'file:' || (typeof ST_UNREPLACED !== 'undefined' && raw && raw.indexOf(ST_UNREPLACED) !== -1));
      if (content && !content.querySelector('.evt') && slotOpen) {
        content.insertAdjacentHTML('beforeend', renderSuddenEvent(EVT_DEMO, 0));
      }
      evtRefreshChoices(document);
    }

    const AVATAR_CACHE_PREFIX = 'custom_char_avatar_';
    const CHAR_CACHE_KEY = 'custom_char_cache';

    function getAllCachedChars() {
      try {
        const raw = localStorage.getItem(CHAR_CACHE_KEY);
        return raw ? JSON.parse(raw) : {};
      } catch (e) { return {}; }
    }

    function saveCachedChars(chars) {
      try {
        localStorage.setItem(CHAR_CACHE_KEY, JSON.stringify(chars));
        return true;
      } catch (e) {
        console.warn('Custom character cache write failed:', e);
        return false;
      }
    }

    function normalizeAvatarNetworkUrl(value) {
      const raw = String(value || '').trim();
      if (!raw) return '';
      try {
        const url = new URL(raw, window.location.href);
        return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : '';
      } catch (e) { return ''; }
    }

    function isLocalAvatarData(value) {
      return /^data:image\//i.test(String(value || ''));
    }

    function estimateAvatarStorageBytes(value) {
      return String(value || '').length * 2;
    }

    function getLocalAvatarCacheUsageBytes(excludeName = '') {
      let total = 0;
      try {
        for (let i = 0; i < localStorage.length; i++) {
          const key = localStorage.key(i) || '';
          if (!key.startsWith(AVATAR_CACHE_PREFIX)) continue;
          const name = key.slice(AVATAR_CACHE_PREFIX.length);
          if (excludeName && name === excludeName) continue;
          const value = localStorage.getItem(key) || '';
          if (isLocalAvatarData(value)) total += estimateAvatarStorageBytes(value);
        }
      } catch (e) { }
      return total;
    }

    function formatAvatarBytes(bytes) {
      if (bytes < 1024) return bytes + ' B';
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
      return (bytes / 1024 / 1024).toFixed(2) + ' MB';
    }

    function updateAvatarStorageHint() {
      const hint = document.getElementById('customCharStorageHint');
      if (!hint || typeof AVATAR_CACHE_TOTAL_MAX_BYTES === 'undefined') return;
      const used = getLocalAvatarCacheUsageBytes();
      hint.textContent = '\u672c\u5730\u5934\u50cf\u7f13\u5b58\uff1a' + formatAvatarBytes(used) + ' / ' + formatAvatarBytes(AVATAR_CACHE_TOTAL_MAX_BYTES) + '\uff1b\u7f51\u7edc\u94fe\u63a5\u4e0d\u8ba1\u5165\u4e0a\u9650';
    }

    function saveAvatarToCache(charName, avatarValue) {
      const value = String(avatarValue || '');
      if (isLocalAvatarData(value)) {
        const projected = getLocalAvatarCacheUsageBytes(charName) + estimateAvatarStorageBytes(value);
        if (projected > AVATAR_CACHE_TOTAL_MAX_BYTES) return { ok: false, reason: 'limit', projected };
      }
      try {
        localStorage.setItem(AVATAR_CACHE_PREFIX + charName, value);
        return { ok: true };
      } catch (e) {
        console.warn('Avatar cache write failed:', e);
        return { ok: false, reason: 'storage', error: e };
      }
    }

    function getAvatarFromCache(charName) {
      try { return localStorage.getItem(AVATAR_CACHE_PREFIX + charName) || ''; } catch (e) { return ''; }
    }

    function removeAvatarFromCache(charName) {
      try { localStorage.removeItem(AVATAR_CACHE_PREFIX + charName); } catch (e) { }
      updateAvatarStorageHint();
    }

    // ==================== 浏览器缓存角色 ====================
    function injectCustomCharCSS(name, color) {
      if (!color) return;
      const styleId = 'custom-char-css-' + name;
      if (document.getElementById(styleId)) document.getElementById(styleId).remove();
      const style = document.createElement('style');
      style.id = styleId;
      const darkColor = lightenColor(color, 50);
      style.textContent = `.char-${CSS.escape(name)} .character-name .name-main { color: ${color} }
.name-initial-${CSS.escape(name)} { color: ${color}; }
body[data-theme="dark"] .char-${CSS.escape(name)} .character-name .name-main { color: ${darkColor} }
body[data-theme="dark"] .name-initial-${CSS.escape(name)} { color: ${darkColor}; }`;
      document.head.appendChild(style);
    }

    function lightenColor(hex, amount) {
      const num = parseInt(hex.replace('#', ''), 16);
      let r = Math.min(255, (num >> 16) + amount);
      let g = Math.min(255, ((num >> 8) & 0xff) + amount);
      let b = Math.min(255, (num & 0xff) + amount);
      return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
    }

