        const nk = key.trim().normalize('NFC');
        return nk === ns || nk.replace(/\s/g, '') === ns.replace(/\s/g, '');
      });
      if (!sceneKey) return null;
      const numbers = Array.isArray(characterData[sceneKey]) ? characterData[sceneKey] : [];
      return { characterKey, sceneKey, numbers, maxNumber: numbers.length };
    }

    const CG_UNLOCK_CHANNEL = 'linjiang-cg-unlock';

    function publishCGUnlock(category, entry) {
      const payload = {
        channel: CG_UNLOCK_CHANNEL,
        type: 'record',
        id: `cg-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        category,
        character: entry.characterKey,
        scene: entry.sceneKey,
        count: entry.maxNumber
      };
      const targets = [];
      try { if (window.parent) targets.push(window.parent); } catch (e) {}
      try { if (window.top && !targets.includes(window.top)) targets.push(window.top); } catch (e) {}
      const send = () => targets.forEach(target => {
        try { target.postMessage(payload, '*'); } catch (e) {}
      });
      send();
      // 状态栏可能正处于楼层交接，短暂重发；接收端按 id 去重。
      setTimeout(send, 300);
      setTimeout(send, 1200);
    }

    window.recordCGUnlock = function (imgSrc) {
      try {
        const parsed = new URL(String(imgSrc || ''), window.location.href);
        const parts = parsed.pathname.split('/').filter(Boolean);
        const ci = parts.findIndex(part => part === 'NSFW' || part === 'SFW');
        if (ci < 0 || ci + 2 >= parts.length) return;
        const category = parts[ci];
        const character = safeDecodeURIComponent(parts[ci + 1]);
        const fileName = safeDecodeURIComponent(parts[ci + 2]).replace(/\.webp$/i, '');
        const match = fileName.match(/^(.+?)(\d+)$/);
        if (!match) return;
        const entry = findImageListEntry(category, character, match[1]);
        if (!entry || !entry.maxNumber) return;
        let unlocked = {};
        try { unlocked = JSON.parse(localStorage.getItem('unlocked_cg') || '{}') || {}; } catch (e) {}
        if (!unlocked[entry.characterKey]) unlocked[entry.characterKey] = {};
        const previous = Number(unlocked[entry.characterKey][entry.sceneKey]) || 0;
        if (previous < entry.maxNumber) {
          unlocked[entry.characterKey][entry.sceneKey] = entry.maxNumber;
          try { localStorage.setItem('unlocked_cg', JSON.stringify(unlocked)); } catch (e) {}
        }
        // 即使正文自己的 localStorage 已记录，也继续通知 HUD，补齐旧版本漏掉的跨域同步。
        publishCGUnlock(category, entry);
      } catch (e) { console.error('CG unlock record failed:', e); }
    };

    window.refreshImage = function (imageId, event) {
      const box = document.getElementById(imageId);
      const img = box && box.querySelector('img');
      if (!img) return;
      const button = event && event.target.closest('.image-refresh-btn');
      if (button) { button.style.transform = 'rotate(360deg)'; setTimeout(() => button.style.transform = '', 500); }
      const restore = () => { img.style.opacity = '1'; };
      img.style.opacity = '0.5';
      try {
        const parts = (img.currentSrc || img.src).split('/');
        const ci = parts.findIndex(part => part === 'NSFW' || part === 'SFW');
        if (ci < 0 || ci + 2 >= parts.length) { restore(); return; }
        const character = safeDecodeURIComponent(parts[ci + 1]);
        const fileName = safeDecodeURIComponent(parts[ci + 2]).replace(/\.webp(?:[?#].*)?$/i, '');
        const match = fileName.match(/^(.+?)(\d+)$/);
        const type = match ? match[1] : fileName;
        const current = match ? Number.parseInt(match[2], 10) : 0;
        const entry = findImageListEntry(parts[ci], character, type);
        if (!entry || !entry.maxNumber) { restore(); return; }
        const pool = entry.numbers.filter(n => n !== current);
        const choices = pool.length ? pool : entry.numbers;
        const next = choices[Math.floor(Math.random() * choices.length)];
        parts[ci + 2] = encodeURIComponent(type + next + '.webp');
        const onLoad = () => { cleanup(); restore(); img.style.width = imageSize + '%'; img.style.maxWidth = imageSize + '%'; recordCGUnlock(img.currentSrc || img.src); };
        const onError = () => { cleanup(); restore(); };
        const cleanup = () => { img.removeEventListener('load', onLoad); img.removeEventListener('error', onError); };
        img.addEventListener('load', onLoad, { once: true });
        img.addEventListener('error', onError, { once: true });
        img.src = parts.join('/');
      } catch (e) { restore(); console.error('Image refresh failed:', e); }
    };

    function safeDecodeURIComponent(str) {
